package com.greenocean.backend;
import com.greenocean.backend.wellbeing.service.*;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseO4RewardsTest extends PhaseO3Fixtures {
 @Autowired GrowthRewards rewards;@Autowired jakarta.persistence.EntityManager entities;
 UUID key(UUID course,int position){var rows=(List<Map<String,Object>>)learning.progress(learner.id(),course).get("lessons");return(UUID)rows.get(position).get("lesson_key");}
 void finish(UUID course,int position){UUID key=key(course,position);var opened=learning.open(learner.id(),course,key);learning.complete(learner.id(),course,key,new LearningCourses.Completion(opened.get("content_digest").toString(),true));}
 long total(UUID user){return((Number)rewards.dashboard(user,0).get("balance")).longValue();}
 @Test @Tag("happy") void genuineLearningProducesExactlyOnePrivateLedgerPerMilestone(){UUID course=create();publish(course);finish(course,0);finish(course,0);assertThat(total(learner.id())).isEqualTo(10);UUID key=key(course,0);var open=learning.open(learner.id(),course,key);learning.check(learner.id(),course,key,new LearningCourses.Check(open.get("content_digest").toString(),1));assertThat(total(learner.id())).isEqualTo(10);learning.check(learner.id(),course,key,new LearningCourses.Check(open.get("content_digest").toString(),0));learning.check(learner.id(),course,key,new LearningCourses.Check(open.get("content_digest").toString(),0));finish(course,1);finish(course,1);assertThat(total(learner.id())).isEqualTo(55);assertThat(rewards.dashboard(learner.id(),0).get("badges").toString()).contains("FIRST_LESSON","FIRST_COURSE");assertThat(total(other.id())).isZero();}
 @Test @Tag("malicious") void arbitraryClientPointsAndOwnerOverrideAreNotEndpoints()throws Exception{mvc.perform(post("/api/v1/wellbeing/growth-rewards").header("Authorization","Bearer "+learner.token()).contentType("application/json").content("{\"point_delta\":999,\"owner_id\":\""+other.id()+"\"}")).andExpect(status().isMethodNotAllowed());UUID course=create();publish(course);finish(course,0);mvc.perform(get("/api/v1/wellbeing/growth-rewards").param("owner",learner.id().toString()).header("Authorization","Bearer "+other.token())).andExpect(status().isOk()).andExpect(jsonPath("$.balance").value(0));}
 @Test @Tag("malicious") void forgedCompletionOrDifferentOwnerCreatesNoCredit(){rewards.completed(new LearningCourses.LearningEvent(learner.id(),"LESSON",UUID.randomUUID()));UUID course=create();publish(course);finish(course,0);UUID completion=db.queryForObject("SELECT id FROM learning_lesson_completions WHERE owner_id=?",UUID.class,learner.id());rewards.completed(new LearningCourses.LearningEvent(other.id(),"LESSON",completion));assertThat(total(other.id())).isZero();}
 @Test @Tag("confused") void courseRevisionsDoNotFarmPoints(){UUID id=create();publish(id);finish(id,0);finish(id,1);var next=library.editorial(author.id(),id);var changed=new LinkedHashMap<String,Object>((Map<String,Object>)next.get("document"));var mods=(List<Map<String,Object>>)changed.get("modules");var lessons=(List<Map<String,Object>>)mods.getFirst().get("lessons");lessons.getFirst().put("body","Changed original educational text about choosing a manageable plan, adapting resources and avoiding pressure. Participation is optional and does not measure your worth.");library.edit(author.id(),id,new com.greenocean.backend.catalog.service.GrowthLibrary.Draft(changed,((Number)next.get("revision")).intValue(),((Number)next.get("etag")).longValue()),true);publish(id);finish(id,0);assertThat(total(learner.id())).isEqualTo(50);}
 @Test @Tag("happy") void auditedReversalIsIdempotentAndCannotBeReissued(){UUID course=create();publish(course);finish(course,0);UUID event=db.queryForObject("SELECT id FROM growth_reward_ledger WHERE owner_id=?",UUID.class,learner.id());rewards.reverse(issuer.id(),event,"Synthetic correction of invalid credit");rewards.reverse(issuer.id(),event,"Synthetic repeated correction request");finish(course,0);rewards.reconcile(issuer.id(),learner.id(),"Synthetic reconciliation after correction");assertThat(total(learner.id())).isZero();assertThat(db.queryForObject("SELECT count(*) FROM growth_reward_ledger WHERE reversal_of=?",Integer.class,event)).isEqualTo(1);assertThat(db.queryForObject("SELECT revoked_at IS NOT NULL FROM growth_learning_badges WHERE owner_id=? AND code='FIRST_LESSON'",Boolean.class,learner.id())).isTrue();}
 @Test @Tag("malicious") void ordinaryMemberCannotCorrectAndPreMfaStaffIsDenied()throws Exception{entities.clear();assertThatThrownBy(()->rewards.reconcile(learner.id(),learner.id(),"Unauthorized reconciliation attempt")).isInstanceOf(ForbiddenException.class);mvc.perform(post("/api/v1/admin/growth-rewards/owners/"+learner.id()+"/reconcile").header("Authorization","Bearer "+PhaseIFixtures.session(db,users,tokens,issuer.id()).token()).contentType("application/json").content("{\"reason\":\"Synthetic correction case\"}")).andExpect(status().isForbidden());}
 @Test @Tag("happy") void completionDeletionReversesItsCredit(){UUID course=create();publish(course);finish(course,0);db.update("DELETE FROM learning_lesson_completions WHERE owner_id=?",learner.id());assertThat(total(learner.id())).isZero();assertThat(rewards.dashboard(learner.id(),0).get("events").toString()).contains("reversal_of");}
 @Test @Tag("happy") void accountRightsExportAndEraseAllPrivateRewards(){UUID course=create();publish(course);finish(course,0);assertThat(archives.archive(learner.id()).privateWellbeing().toString()).contains("growthRewards","learningBadges","FIRST_LESSON");assertThat(archives.archive(other.id()).privateWellbeing().get("growthRewards").toString()).isEqualTo("[]");erasure.erase(learner.id());assertThat(db.queryForObject("SELECT count(*) FROM growth_reward_ledger WHERE owner_id=?",Integer.class,learner.id())).isZero();assertThat(db.queryForObject("SELECT count(*) FROM growth_learning_badges WHERE owner_id=?",Integer.class,learner.id())).isZero();}
 @Test @Tag("malicious") void sensitiveWritingDoesNotGenerateRewards(){privateData.write(learner.id(),null,new PrivateWellbeing.Writing("Private title","Private synthetic writing",null,List.of(),0,UUID.randomUUID()));assertThat(total(learner.id())).isZero();assertThat(rewards.dashboard(learner.id(),0).toString()).doesNotContain("Private synthetic writing");}
 @Test @Tag("confused") void retirementPreservesEarnedCreditWithoutNewCredit(){UUID course=create();publish(course);finish(course,0);library.transition(reviewer.id(),course,decision(course,"RETIRE"));rewards.reconcile(issuer.id(),learner.id(),"Synthetic reconciliation of retired course");assertThat(total(learner.id())).isEqualTo(10);assertThatThrownBy(()->finish(course,1)).isInstanceOf(NotFoundException.class);}
 @Test void directLedgerAmountForgeryIsRejected(){UUID course=create();publish(course);finish(course,0);assertThatThrownBy(()->db.update("INSERT INTO growth_reward_ledger(owner_id,source_type,completion_id,course_key,activity_key,rule_version,point_delta) SELECT owner_id,source_type,completion_id,course_key,activity_key,rule_version,999 FROM growth_reward_ledger WHERE owner_id=?",learner.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void oldRuleCannotBeSilentlyRepriced(){assertThatThrownBy(()->db.update("UPDATE growth_reward_rules SET lesson_points=999 WHERE version=1")).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void awardedEventCannotBeOverwritten(){UUID course=create();publish(course);finish(course,0);assertThatThrownBy(()->db.update("UPDATE growth_reward_ledger SET point_delta=999 WHERE owner_id=?",learner.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);}
}
